/* SD Akademie – JavaScript Grundlagen. */
(function(root){"use strict";root.SDAkademieKurse=root.SDAkademieKurse||Object.create(null);root.SDAkademieKurse["javascript"]=[{"id":"p3-1","title":"Datentypen","minutes":25,"ziel":"Zahlen, Text und Boolean unterscheiden","schritte":[{"titel":"Zahlen ohne Anführungszeichen","text":"Eine Zahl wie 12 lässt sich direkt berechnen. Ohne Anführungszeichen speichert JavaScript einen numerischen Wert. Für einen festen Preis ist const geeignet. Ein Preisetikett trägt eine Zahl, nicht den geschriebenen Namen der Zahl. Zeile 1 legt preis mit `const` fest; Zeile 2 legt ort als Zeichenkette an. Vergleiche `12 + 3` mit `'12' + 3` und beobachte `15` gegenüber `123`.","code":"const preis = 12; const ort = 'Bonn'; const offen = true;","erklaerung":"Zeile 1 legt preis mit `const` fest; Zeile 2 legt ort als Zeichenkette an. Vergleiche `12 + 3` mit `'12' + 3` und beobachte `15` gegenüber `123`.","tiefer":["JavaScript kennt nur einen Zahltyp, `number`, für ganze Zahlen und Kommazahlen gemeinsam. Intern sind es 64-Bit-Gleitkommazahlen, deshalb ergibt `0.1 + 0.2` auch hier `0.30000000000000004`. Für sehr große ganze Zahlen gibt es zusätzlich den Typ `bigint`, erkennbar am `n` hinter der Zahl.","`const` legt eine Variable an, die nicht neu zugewiesen werden kann; `let` erlaubt eine spätere Änderung. Das ältere `var` solltest du nicht mehr verwenden, weil es sich bei Gültigkeitsbereichen überraschend verhält. Gute Regel: Nimm `const`, solange du nicht weißt, dass sich der Wert ändern muss."]},{"titel":"Strings als Textwerte","text":"Ein Ortsname wird als String gespeichert. Dafür schreibst du den Text zwischen Anführungszeichen. Mit einem Pluszeichen lassen sich zwei Strings verbinden. Eine Postkarte enthält Buchstaben und wird nicht wie ein Geldbetrag addiert. `const ort = 'Bonn';` bindet den Text Bonn an den Namen ort. `console.log(ort)` schreibt diesen Text in die Entwicklerkonsole. Setze statt Bonn deinen eigenen Wohnort ein und behalte die Anführungszeichen.","code":"const preis = 12; const ort = 'Bonn'; const offen = true;","erklaerung":"`const ort = 'Bonn';` bindet den Text Bonn an den Namen ort. `console.log(ort)` schreibt diesen Text in die Entwicklerkonsole.","tiefer":["Strings dürfen in einfachen `'...'` oder doppelten `\"...\"` Anführungszeichen stehen. Mit Backticks entstehen Template-Strings, in die man Werte mit `${...}` einsetzt – ähnlich wie f-Strings in Python. Template-Strings dürfen außerdem über mehrere Zeilen gehen.","Vorsicht beim Pluszeichen: Ist einer der Werte ein String, verbindet JavaScript statt zu rechnen. `'5' + 3` ergibt `'53'`, `'5' - 3` dagegen `2`, weil Minus nur für Zahlen definiert ist. Mit `Number('5')` wandelst du einen Text ausdrücklich in eine Zahl um."]},{"titel":"Boolean true und false","text":"Ein Boolean ist entweder true oder false. Er steht ohne Anführungszeichen im Code. So kannst du Zustände wie offen oder geschlossen speichern. Ein Lichtschalter hat zwei Zustände; Boolean bildet genau diese Unterscheidung ab. `const offen = true;` legt einen echten Wahrheitswert an. `if (offen)` kann damit eine Entscheidung treffen, ohne Text zu vergleichen.","code":"const preis = 12; const ort = 'Bonn'; const offen = true;","erklaerung":"`const offen = true;` legt einen echten Wahrheitswert an. `if (offen)` kann damit eine Entscheidung treffen, ohne Text zu vergleichen.","tiefer":["Booleans entstehen meist aus Vergleichen. Verwende in JavaScript immer `===` und `!==`: Sie prüfen Wert und Typ. Das ältere `==` wandelt vorher Typen um, sodass `'0' == 0` wahr ist – eine bekannte Fehlerquelle.","In Bedingungen behandelt JavaScript bestimmte Werte als „falsy“: `false`, `0`, `''` (leerer Text), `null`, `undefined` und `NaN`. Alle anderen Werte gelten als „truthy“, sogar `'0'` und ein leeres Array `[]`. Wer diese Regel kennt, versteht viele überraschende Ergebnisse."]},{"titel":"Mit typeof kontrollieren","text":"typeof zeigt den Typ eines Werts an. typeof 12 liefert number, typeof '12' liefert string. Teste den Unterschied in der Konsole. Ein Etikett am Vorratsglas sagt dir, was darin liegt; `typeof` übernimmt diese Aufgabe für Werte. `console.log(typeof 12);` zeigt `number` als Typ an. `console.log(typeof '12');` zeigt `string`, obwohl die Zeichen gleich aussehen. Notiere beide Ergebnisse, bevor du weitere Werte ausprobierst.","code":"const preis = 12; const ort = 'Bonn'; const offen = true;","erklaerung":"`console.log(typeof 12);` zeigt `number` als Typ an. `console.log(typeof '12');` zeigt `string`, obwohl die Zeichen gleich aussehen.","tiefer":["Neben `number`, `string` und `boolean` gibt es die Grundtypen `undefined` (kein Wert zugewiesen), `null` (bewusst leer), `bigint` und `symbol`. Alles andere – Arrays, Funktionen, Objekte – ist ein Objekt. Ein bekannter historischer Fehler: `typeof null` liefert `'object'`.","Für Arrays liefert `typeof` ebenfalls `'object'`. Ob etwas ein Array ist, prüfst du mit `Array.isArray(wert)`. JavaScript ist dynamisch typisiert: Eine mit `let` angelegte Variable kann später einen Wert anderen Typs bekommen. TypeScript ergänzt Typprüfungen wie in C++ und Rust."]}],"beispiel":{"html":"<h1>Datentypen</h1><p id='ausgabe'></p>","css":"","js":""},"aufgabe":{"text":"Setze das Beispiel im Editor um und kontrolliere die Vorschau oder Konsole.","tipp":"Vergleiche die Schreibweise mit dem Codebeispiel.","pruefungen":[{"beschreibung":"Passende HTML-Struktur vorhanden.","test":"p3-1-html"},{"beschreibung":"JavaScript enthält die geübte Technik.","test":"p3-1-js"}],"loesung":{"html":"<h1>Datentypen</h1><p id='ausgabe'></p>","css":"","js":"const preis = 12; const ort = 'Bonn'; const offen = true;"}},"fehler":[{"titel":"Zahl als Text gespeichert","text":"Falsch: `const preis = '12'; console.log(preis + 3);` ergibt `123` statt `15` in der Konsole. Der Preis ist ein String und das Pluszeichen hängt Text an. Richtig: `const preis = 12; console.log(preis + 3);` zeigt `15`."},{"titel":"Boolean fälschlich in Anführungszeichen","text":"Falsch: `const offen = 'false'; if (offen) console.log('offen');` zeigt trotzdem `offen`, weil der nichtleere String als wahr gilt. Richtig: `const offen = false; if (offen) console.log('offen');` zeigt keine Meldung."}],"quiz":[{"frage":"Was ist typeof 12?","antworten":["string","number","boolean"],"richtig":1,"erklaerung":"Hier passt „number“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Was ist typeof '12'?","antworten":["number","boolean","string"],"richtig":2,"erklaerung":"Hier passt „string“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion."]},{"frage":"Welcher Wert ist ein Boolean?","antworten":["true","'true'","12"],"richtig":0,"erklaerung":"Hier passt „true“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]}],"merke":["Bei Datentypen ist die genaue JavaScript-Schreibweise wichtig.","Nutze die Lösung `const preis = 12; const ort = 'Bonn'; const offen = true;` als Vergleich für deine eigene Übung."]},{"id":"p3-2","title":"Arrays","minutes":25,"ziel":"Mehrere Einträge in einer Liste speichern","schritte":[{"titel":"Eine Einkaufsliste anlegen","text":"Ein Array sammelt mehrere Werte in eckigen Klammern. Trenne die Einträge mit Kommas. So bleibt eine Einkaufsliste in einer einzigen Variablen. Eine Einkaufstasche enthält mehrere Produkte; ein Array hält ihre Namen zusammen. `const einkauf = ['Brot', 'Milch'];` erzeugt zwei Einträge. Die eckigen Klammern gehören zur Liste, die Anführungszeichen zu jedem Text.","code":"const einkauf = ['Brot','Milch']; einkauf.push('Reis'); console.log(einkauf.length);","erklaerung":"`const einkauf = ['Brot', 'Milch'];` erzeugt zwei Einträge. Die eckigen Klammern gehören zur Liste, die Anführungszeichen zu jedem Text.","tiefer":["Arrays dürfen Werte verschiedener Typen mischen und sogar weitere Arrays enthalten. Auch mit `const` angelegt, bleibt das Array veränderbar: `const` verhindert nur, dass die Variable auf ein anderes Array zeigt, nicht dass sich der Inhalt ändert.","Arrays sind in JavaScript Objekte, und Variablen speichern einen Verweis darauf. Bei `const b = a;` zeigen beide Namen auf dasselbe Array – eine Änderung über `b` sieht man auch über `a`. Eine echte Kopie erstellst du mit `[...a]`."]},{"titel":"Einträge mit Index lesen","text":"Die erste Position eines Arrays hat den Index null. einkauf[0] liefert daher Brot. Der zweite Eintrag wird über einkauf[1] gelesen. Regalfächer haben Nummern; JavaScript beginnt die Nummerierung bei null. `console.log(einkauf[0]);` liest Brot aus dem ersten Fach. `console.log(einkauf[1]);` liest Milch aus dem zweiten Fach. Ein Zugriff auf `einkauf[9]` liefert dagegen `undefined`.","code":"const einkauf = ['Brot','Milch']; einkauf.push('Reis'); console.log(einkauf.length);","erklaerung":"`console.log(einkauf[0]);` liest Brot aus dem ersten Fach. `console.log(einkauf[1]);` liest Milch aus dem zweiten Fach.","tiefer":["Ein Zugriff auf eine Position, die es nicht gibt, liefert in JavaScript keinen Fehler, sondern `undefined`. Das ist bequem, kann aber Fehler verschleiern. Den letzten Eintrag erreichst du mit `einkauf.at(-1)` oder `einkauf[einkauf.length - 1]`.","Mit `einkauf.indexOf('Milch')` findest du die Position eines Werts; fehlt er, ergibt sich `-1`. `einkauf.includes('Milch')` antwortet einfach mit `true` oder `false`. Beide vergleichen mit `===`."]},{"titel":"Mit push erweitern","text":"Mit push fügst du einen neuen Eintrag am Ende hinzu. Die vorhandenen Werte bleiben erhalten. Probiere einkauf.push('Reis') in deinem Beispiel aus. Beim Einkaufen legst du neue Waren hinten in die Tasche; so arbeitet push. `einkauf.push('Reis');` ergänzt den String Reis. `console.log(einkauf);` zeigt danach alle drei Namen. Die Methode braucht runde Klammern und den gewünschten Wert.","code":"const einkauf = ['Brot','Milch']; einkauf.push('Reis'); console.log(einkauf.length);","erklaerung":"`einkauf.push('Reis');` ergänzt den String Reis. `console.log(einkauf);` zeigt danach alle drei Namen.","tiefer":["`push` verändert das Array direkt und gibt die neue Länge zurück. Weitere wichtige Methoden: `pop` entfernt den letzten Eintrag, `unshift` und `shift` arbeiten am Anfang, `splice` fügt an beliebiger Stelle ein oder entfernt. Methoden, die das Original verändern, nennt man mutierend.","In modernen Webanwendungen, etwa mit React, erstellt man oft lieber ein neues Array, statt das alte zu verändern: `const neu = [...einkauf, 'Reis'];`. So lässt sich leichter erkennen, ob sich Daten geändert haben. Beide Stile haben ihren Platz."]},{"titel":"Die Länge abfragen","text":"length gibt die Anzahl der Einträge zurück. Nach dem Hinzufügen sind es drei. Verwende die Eigenschaft ohne Klammern. Ein Kassenbon zählt Positionen, nicht den letzten Regalindex. `console.log(einkauf.length);` liefert nach push den Wert drei. Die Eigenschaft length wird ohne `()` geschrieben. Lösche testweise einen Eintrag und vergleiche die neue Anzahl.","code":"const einkauf = ['Brot','Milch']; einkauf.push('Reis'); console.log(einkauf.length);","erklaerung":"`console.log(einkauf.length);` liefert nach push den Wert drei. Die Eigenschaft length wird ohne `()` geschrieben.","tiefer":["`length` ist immer um eins größer als der höchste Index, weil die Zählung bei null beginnt. Ein Array mit drei Einträgen hat die Indizes 0, 1 und 2. Darum lautet die Bedingung in Zählschleifen `i < liste.length` und nicht `<=`.","Man kann `length` sogar setzen: `einkauf.length = 0` leert das Array vollständig. Das wirkt auf alle Variablen, die auf dasselbe Array verweisen. Für Neulinge ist `einkauf = []` mit `let` oft verständlicher, erzeugt aber ein neues Array."]}],"beispiel":{"html":"<h1>Einkaufsliste</h1><ul id='liste'></ul>","css":"","js":""},"aufgabe":{"text":"Setze das Beispiel im Editor um und kontrolliere die Vorschau oder Konsole.","tipp":"Vergleiche die Schreibweise mit dem Codebeispiel.","pruefungen":[{"beschreibung":"Passende HTML-Struktur vorhanden.","test":"p3-2-html"},{"beschreibung":"JavaScript enthält die geübte Technik.","test":"p3-2-js"}],"loesung":{"html":"<h1>Einkaufsliste</h1><ul id='liste'></ul>","css":"","js":"const einkauf = ['Brot','Milch']; einkauf.push('Reis'); console.log(einkauf.length);"}},"fehler":[{"titel":"Ersten Eintrag mit Index eins gesucht","text":"Falsch: `console.log(einkauf[1]);` zeigt `Milch`, obwohl du `Brot` erwartest. Arrays zählen ab null. Richtig: `console.log(einkauf[0]);` zeigt `Brot`."},{"titel":"push ohne Argument verwendet","text":"Falsch: `einkauf.push();` fügt einen Eintrag mit dem Wert `undefined` hinzu; die Liste enthält danach keinen neuen Artikelnamen. Richtig: `einkauf.push('Reis');` ergänzt einen sichtbaren Einkauf."}],"quiz":[{"frage":"Welcher Index ist der erste?","antworten":["1","0","2"],"richtig":1,"erklaerung":"Hier passt „0“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Wie wird Reis angehängt?","antworten":["einkauf.add('Reis')","einkauf[0]","einkauf.push('Reis')"],"richtig":2,"erklaerung":"Hier passt „einkauf.push('Reis')“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion."]},{"frage":"Was liefert length?","antworten":["Anzahl der Einträge","Ersten Text","Letzten Namen"],"richtig":0,"erklaerung":"Hier passt „Anzahl der Einträge“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]}],"merke":["Bei Arrays ist die genaue JavaScript-Schreibweise wichtig.","Nutze die Lösung `const einkauf = ['Brot','Milch']; einkauf.push('Reis'); console.log(einkauf.length);` als Vergleich für deine eigene Übung."]},{"id":"p3-3","title":"Schleifen","minutes":25,"ziel":"Wiederholungen mit for und for...of schreiben","schritte":[{"titel":"Wiederholung verstehen","text":"Eine Schleife führt denselben Ablauf mehrmals aus. Du musst die Anweisung nicht kopieren. Das ist bei einer Liste von Namen besonders praktisch. Eine Lehrkraft ruft alle Namen der Anwesenheitsliste nacheinander auf. `for (const name of namen)` besucht jeden vorhandenen Eintrag. Der Block in geschweiften Klammern wird für jeden Namen wiederholt.","code":"const namen = ['Ali','Mina']; for (const name of namen) { console.log(name); }","erklaerung":"`for (const name of namen)` besucht jeden vorhandenen Eintrag. Der Block in geschweiften Klammern wird für jeden Namen wiederholt.","tiefer":["Schleifen setzen das DRY-Prinzip um: Don't Repeat Yourself. Statt dieselbe Zeile zehnmal zu schreiben, beschreibst du einmal, was für jedes Element passieren soll. Ändert sich die Liste, passt sich die Schleife automatisch an.","JavaScript kennt mehrere Schleifenarten: `for`, `for...of`, `while`, `do...while` und `for...in`. Hinzu kommen Array-Methoden wie `forEach`, `map` und `filter`, die in modernem Code sehr häufig sind und eine Schleife oft ersetzen."]},{"titel":"for...of für Arrays","text":"for...of liest die Einträge nacheinander. Der Name im Schleifenkopf steht jeweils für den aktuellen Eintrag. Innerhalb der Klammern kannst du ihn ausgeben. Wie bei einer Runde durch mehrere Zimmer wird derselbe Arbeitsschritt wiederholt. `console.log(name);` verwendet im Block den jeweils aktuellen Namen. Nach dem letzten Eintrag endet for...of automatisch. Prüfe die Ausgabe mit einer Liste aus drei Personen.","code":"const namen = ['Ali','Mina']; for (const name of namen) { console.log(name); }","erklaerung":"`console.log(name);` verwendet im Block den jeweils aktuellen Namen. Nach dem letzten Eintrag endet for...of automatisch.","tiefer":["`for...of` funktioniert mit allem, was iterierbar ist: Arrays, Strings (Zeichen für Zeichen), Maps und Sets. Willst du zusätzlich die Position wissen, schreibe `for (const [i, name] of namen.entries())`.","Verwechsle es nicht mit `for...in`: Das liefert die Schlüssel eines Objekts, bei Arrays also die Indizes als Texte. Für Arrays ist `for...of` die richtige Wahl, für die Eigenschaften eines Objekts `Object.entries(obj)`."]},{"titel":"Zähler mit let verwenden","text":"Eine klassische for-Schleife benutzt oft let i = 0. Nach jedem Durchlauf erhöht i++ den Zähler. Mit i < 3 läuft der Block genau dreimal. Eine Nummernausgabe am Schalter zählt 0, 1, 2 und stoppt dann. `let i = 0` setzt den Anfangswert, `i < 3` prüft die Grenze. `i++` erhöht die Nummer nach jedem Durchlauf um eins.","code":"const namen = ['Ali','Mina']; for (const name of namen) { console.log(name); }","erklaerung":"`let i = 0` setzt den Anfangswert, `i < 3` prüft die Grenze. `i++` erhöht die Nummer nach jedem Durchlauf um eins.","tiefer":["Die klassische Schleife hat drei Teile, getrennt durch Semikolons: Start (`let i = 0`), Bedingung (`i < 3`) und Schritt (`i++`). Die Bedingung wird vor jedem Durchlauf geprüft. Der Schritt läuft nach jedem Durchlauf.","Hier muss `let` stehen, nicht `const`, weil sich `i` ändert. Jeder Durchlauf bekommt in JavaScript eine eigene Kopie von `i`. Das ist wichtig, wenn innerhalb der Schleife Funktionen erzeugt werden, die später aufgerufen werden."]},{"titel":"Abbruchbedingung prüfen","text":"Eine Schleife braucht eine erreichbare Abbruchbedingung. Ohne Änderung des Zählers kann sie endlos laufen. Prüfe den Ablauf zunächst mit wenigen Werten. Eine Rolltreppe ohne Ausgang wäre gefährlich; eine Schleife ohne Ende blockiert den Ablauf. Bei `for (let i = 0; i < 3; i++)` ist das Ende erreichbar. Wenn `i++` fehlt, bleibt die Bedingung dauerhaft wahr.","code":"const namen = ['Ali','Mina']; for (const name of namen) { console.log(name); }","erklaerung":"Bei `for (let i = 0; i < 3; i++)` ist das Ende erreichbar. Wenn `i++` fehlt, bleibt die Bedingung dauerhaft wahr.","tiefer":["Eine Endlosschleife blockiert im Browser die gesamte Seite: Weil JavaScript im Browser auf einem einzigen Haupt-Thread läuft, reagieren dann weder Knöpfe noch Scrollen. Nach einiger Zeit bietet der Browser an, das Skript abzubrechen.","Für Daten, die nach und nach eintreffen, nutzt man im Browser keine Warteschleifen, sondern Ereignisse und Zeitgeber wie `setTimeout`. Mit `break` verlässt du eine Schleife vorzeitig, mit `continue` springst du zum nächsten Durchlauf."]}],"beispiel":{"html":"<h1>Schleifen</h1><p id='ausgabe'></p>","css":"","js":""},"aufgabe":{"text":"Setze das Beispiel im Editor um und kontrolliere die Vorschau oder Konsole.","tipp":"Vergleiche die Schreibweise mit dem Codebeispiel.","pruefungen":[{"beschreibung":"Passende HTML-Struktur vorhanden.","test":"p3-3-html"},{"beschreibung":"JavaScript enthält die geübte Technik.","test":"p3-3-js"}],"loesung":{"html":"<h1>Schleifen</h1><p id='ausgabe'></p>","css":"","js":"const namen = ['Ali','Mina']; for (const name of namen) { console.log(name); }"}},"fehler":[{"titel":"Zähler wird nicht erhöht","text":"Falsch: `for (let i = 0; i < 3;) console.log(i);` bleibt bei null und kann den Browser blockieren. Der Zähler ändert sich nie. Richtig: `for (let i = 0; i < 3; i++) console.log(i);` gibt `0`, `1`, `2` aus."},{"titel":"Index läuft über das Arrayende","text":"Falsch: `for (let i = 0; i <= namen.length; i++) console.log(namen[i]);` gibt am Ende `undefined` aus. Der letzte gültige Index ist kleiner als length. Richtig: `for (let i = 0; i < namen.length; i++) console.log(namen[i]);`."}],"quiz":[{"frage":"Was macht for...of?","antworten":["Löscht Elemente","Liest Einträge nacheinander","Öffnet eine Webseite"],"richtig":1,"erklaerung":"Hier passt „Liest Einträge nacheinander“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Wie viele Durchläufe hat i < 3 ab null?","antworten":["Drei","Vier","Zwei"],"richtig":0,"erklaerung":"Hier passt „Drei“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Was vermeidet eine Endlosschleife?","antworten":["Längere Namen","Mehr Farben","Erreichbare Abbruchbedingung"],"richtig":2,"erklaerung":"Hier passt „Erreichbare Abbruchbedingung“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion."]}],"merke":["Bei Schleifen ist die genaue JavaScript-Schreibweise wichtig.","Nutze die Lösung `const namen = ['Ali','Mina']; for (const name of namen) { console.log(name); }` als Vergleich für deine eigene Übung."]},{"id":"p3-4","title":"Funktionen","minutes":25,"ziel":"Eigene Funktionen mit Parametern und return nutzen","schritte":[{"titel":"Funktion benennen","text":"Eine Funktion bündelt einen wiederkehrenden Ablauf. function leitet die Definition ein. Der Name beschreibt die Aufgabe möglichst genau. Eine Kaffeemaschine erledigt nach dem Start immer dieselben Schritte. `function doppelt(zahl)` gibt dem Ablauf einen Namen und einen Parameter. Die geschweiften Klammern umschließen die Rechenanweisung.","code":"function doppelt(zahl) { return zahl * 2; } console.log(doppelt(4));","erklaerung":"`function doppelt(zahl)` gibt dem Ablauf einen Namen und einen Parameter. Die geschweiften Klammern umschließen die Rechenanweisung.","tiefer":["Funktionsnamen beginnen üblicherweise mit einem Verb und werden in camelCase geschrieben, etwa `berechneSumme` oder `zeigeMeldung`. Eine mit `function` deklarierte Funktion kann man schon vor ihrer Definition im Code aufrufen; dieses Verhalten heißt Hoisting.","Daneben gibt es Pfeilfunktionen: `const doppelt = (zahl) => zahl * 2;`. Steht rechts vom Pfeil nur ein Ausdruck, wird er automatisch zurückgegeben. Pfeilfunktionen sind besonders bei kurzen Rückruffunktionen beliebt, etwa für Ereignisse."]},{"titel":"Parameter entgegennehmen","text":"In runden Klammern stehen Parameter. Beim Aufruf wird für jeden Parameter ein Wert übergeben. Im Funktionskörper kannst du damit rechnen. Eine Bestellung nennt die gewünschte Menge; ein Parameter übernimmt diesen Wert. `doppelt(4)` übergibt die Zahl vier an den Parameter zahl. Im Funktionskörper steht dann für zahl genau dieser Wert.","code":"function doppelt(zahl) { return zahl * 2; } console.log(doppelt(4));","erklaerung":"`doppelt(4)` übergibt die Zahl vier an den Parameter zahl. Im Funktionskörper steht dann für zahl genau dieser Wert.","tiefer":["Fehlt beim Aufruf ein Argument, ist der Parameter `undefined` – JavaScript meldet keinen Fehler. Mit einem Standardwert vermeidest du das: `function gruss(name = 'Gast')`. Überzählige Argumente werden ignoriert.","Primitive Werte wie Zahlen und Texte werden als Kopie übergeben. Bei Objekten und Arrays erhält die Funktion einen Verweis: Verändert sie das Objekt, ist die Änderung auch außerhalb sichtbar. Darum sollte eine Funktion übergebene Objekte nur verändern, wenn genau das ihre Aufgabe ist."]},{"titel":"Ergebnis zurückgeben","text":"return liefert ein Ergebnis an den Aufrufer. Eine reine Konsolenausgabe gibt dagegen nicht automatisch einen Wert zurück. Nutze return für weitere Berechnungen. Ein Automat gibt nach dem Einwurf etwas zurück; return ist diese Rückgabe. `return zahl * 2;` berechnet und liefert das Ergebnis. `console.log` kann es anschließend sichtbar machen, ersetzt return aber nicht. Ohne return erhält der Aufrufer den Wert `undefined`.","code":"function doppelt(zahl) { return zahl * 2; } console.log(doppelt(4));","erklaerung":"`return zahl * 2;` berechnet und liefert das Ergebnis. `console.log` kann es anschließend sichtbar machen, ersetzt return aber nicht.","tiefer":["`return` beendet die Funktion sofort; Code danach wird nicht mehr ausgeführt. Ohne `return` liefert jede Funktion `undefined`. Willst du mehrere Werte zurückgeben, nutze ein Objekt oder Array: `return { summe, anzahl };`.","Funktionen, die nur aus ihren Parametern ein Ergebnis berechnen und sonst nichts verändern, heißen reine Funktionen. Sie sind leicht zu testen, weil derselbe Aufruf immer dasselbe Ergebnis liefert. Ausgaben in die Konsole oder Änderungen an der Seite heißen dagegen Nebenwirkungen."]},{"titel":"Funktion aufrufen","text":"Die Definition allein führt den Code noch nicht aus. Erst doppelt(4) startet den Ablauf. Das Ergebnis dieser Rechnung ist acht. Ein beschrifteter Werkzeugkasten lässt dich ein Werkzeug schnell wiederfinden. Der Name doppelt beschreibt die Rechnung besser als ein beliebiger Buchstabe. `console.log(doppelt(4));` startet den Aufruf und zeigt acht. Verwende denselben Funktionsnamen beim Definieren und Aufrufen.","code":"function doppelt(zahl) { return zahl * 2; } console.log(doppelt(4));","erklaerung":"Der Name doppelt beschreibt die Rechnung besser als ein beliebiger Buchstabe. `console.log(doppelt(4));` startet den Aufruf und zeigt acht.","tiefer":["Ohne Klammern ist `doppelt` die Funktion selbst, mit Klammern `doppelt(4)` ihr Ergebnis. Diesen Unterschied brauchst du bei Ereignissen: `knopf.addEventListener('click', speichern)` übergibt die Funktion, damit sie später aufgerufen wird. `speichern()` würde sie sofort ausführen.","Funktionen sind in JavaScript Werte erster Klasse: Man kann sie in Variablen speichern, anderen Funktionen übergeben und aus Funktionen zurückgeben. Darauf beruhen `map`, `filter` und `addEventListener`. Diese Idee stammt aus der funktionalen Programmierung."]}],"beispiel":{"html":"<h1>Funktionen</h1><p id='ausgabe'></p>","css":"","js":""},"aufgabe":{"text":"Setze das Beispiel im Editor um und kontrolliere die Vorschau oder Konsole.","tipp":"Vergleiche die Schreibweise mit dem Codebeispiel.","pruefungen":[{"beschreibung":"Passende HTML-Struktur vorhanden.","test":"p3-4-html"},{"beschreibung":"JavaScript enthält die geübte Technik.","test":"p3-4-js"}],"loesung":{"html":"<h1>Funktionen</h1><p id='ausgabe'></p>","css":"","js":"function doppelt(zahl) { return zahl * 2; } console.log(doppelt(4));"}},"fehler":[{"titel":"Funktion nicht aufgerufen","text":"Falsch: `function doppelt(x) { return x * 2; }` allein erzeugt keine Ausgabe; die Funktion wurde noch nicht gestartet. Richtig: `console.log(doppelt(4));` ruft sie auf und zeigt `8`."},{"titel":"console.log mit return verwechselt","text":"Falsch: `function doppelt(x) { console.log(x * 2); } console.log(doppelt(4));` zeigt zuerst `8`, dann `undefined`. console.log zeigt nur etwas an, gibt aber keinen Rückgabewert zurück. Richtig: `function doppelt(x) { return x * 2; } console.log(doppelt(4));` zeigt nur `8`."}],"quiz":[{"frage":"Wozu dient ein Parameter?","antworten":["Zum Löschen","Für Eingabewerte","Für CSS"],"richtig":1,"erklaerung":"Hier passt „Für Eingabewerte“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Was macht return?","antworten":["Gibt ein Ergebnis zurück","Startet HTML","Öffnet eine Datei"],"richtig":0,"erklaerung":"Hier passt „Gibt ein Ergebnis zurück“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Wann läuft die Funktion?","antworten":["Beim Speichern","Beim Benennen","Beim Aufruf"],"richtig":2,"erklaerung":"Hier passt „Beim Aufruf“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion."]}],"merke":["Bei Funktionen ist die genaue JavaScript-Schreibweise wichtig.","Nutze die Lösung `function doppelt(zahl) { return zahl * 2; } console.log(doppelt(4));` als Vergleich für deine eigene Übung."]},{"id":"p3-5","title":"Objekte","minutes":25,"ziel":"Zusammengehörige Eigenschaften verwalten","schritte":[{"titel":"Personendaten bündeln","text":"Ein Objekt speichert zusammengehörige Angaben. Zwischen geschweiften Klammern stehen Eigenschaft und Wert. Ein Doppelpunkt trennt beide Teile. Eine Kontaktkarte hält Name und Ort einer Person beisammen. `const person = { name: 'Amina', ort: 'Bonn' };` erstellt zwei Eigenschaften. Der Doppelpunkt verbindet jeweils Schlüssel und Wert.","code":"const person = { name: 'Amina', ort: 'Bonn' }; console.log(person.name);","erklaerung":"`const person = { name: 'Amina', ort: 'Bonn' };` erstellt zwei Eigenschaften. Der Doppelpunkt verbindet jeweils Schlüssel und Wert.","tiefer":["Objekte sind Sammlungen von Schlüssel-Wert-Paaren, ähnlich wie Dictionaries in Python. Die Schlüssel sind Texte, die man meist ohne Anführungszeichen schreibt. Werte können alles sein, auch Arrays, andere Objekte oder Funktionen – eine Funktion in einem Objekt heißt Methode.","Die Schreibweise mit geschweiften Klammern heißt Objektliteral. Sie ist auch die Grundlage des Datenformats JSON, mit dem Webseiten und Server Daten austauschen. Gibt es eine Variable mit demselben Namen wie die Eigenschaft, reicht die Kurzform `{ name, ort }`."]},{"titel":"Eigenschaften mit Punkt lesen","text":"Mit person.name liest du eine Eigenschaft. Du brauchst dafür keine zusätzliche Variable. Der Punkt verbindet den Objektnamen mit dem Eigenschaftsnamen. Auf einer Karte suchst du die Zeile Name, nicht die ganze Karte. `person.name` liest nur den gespeicherten Namen. `console.log(person.name);` zeigt ihn in der Konsole. Schreibst du versehentlich Name groß, erhältst du möglicherweise undefined.","code":"const person = { name: 'Amina', ort: 'Bonn' }; console.log(person.name);","erklaerung":"`person.name` liest nur den gespeicherten Namen. `console.log(person.name);` zeigt ihn in der Konsole.","tiefer":["Neben der Punktschreibweise gibt es die Klammerschreibweise: `person['name']`. Sie ist nötig, wenn der Name in einer Variable steht (`person[feld]`) oder Sonderzeichen enthält. Mit `const { name, ort } = person;` holst du mehrere Eigenschaften auf einmal heraus; das nennt man Destrukturierung.","`Object.keys(person)` liefert alle Schlüssel als Array, `Object.values(person)` alle Werte und `Object.entries(person)` Paare aus beidem. Damit kannst du mit einer Schleife über alle Eigenschaften eines Objekts laufen."]},{"titel":"Eigenschaften ändern","text":"Eine Eigenschaft lässt sich mit person.ort = 'Köln' ändern. Das ist auch bei einem mit const angelegten Objekt erlaubt. Die gesamte Variable darf jedoch nicht neu zugewiesen werden. Eine Adresse auf einer Kontaktkarte darf sich nach einem Umzug ändern. `person.ort = 'Köln';` ersetzt nur den Wert der Eigenschaft ort. Die Variable person bleibt weiterhin dasselbe Objekt. Prüfe die Änderung mit einer anschließenden Konsolenausgabe.","code":"const person = { name: 'Amina', ort: 'Bonn' }; console.log(person.name);","erklaerung":"`person.ort = 'Köln';` ersetzt nur den Wert der Eigenschaft ort. Die Variable person bleibt weiterhin dasselbe Objekt.","tiefer":["Neue Eigenschaften entstehen einfach durch Zuweisung, etwa `person.alter = 34`. Mit `delete person.alter` entfernst du eine Eigenschaft wieder. Willst du ein Objekt vollständig gegen Änderungen schützen, gibt es `Object.freeze(person)`.","Weil Variablen bei Objekten nur Verweise speichern, ist `const kopie = person;` keine Kopie. Eine flache Kopie entsteht mit `{ ...person }`. Enthält das Objekt weitere Objekte, kopiert `structuredClone(person)` auch diese verschachtelten Teile."]},{"titel":"Fehlende Werte erkennen","text":"Ein falsch geschriebener Eigenschaftsname liefert oft undefined. Prüfe die genaue Schreibweise. Gleiche Namen machen mehrere Objekte leichter vergleichbar. Fehlt ein Feld auf einer Karte, kannst du seinen Inhalt nicht lesen. `person.alter` liefert undefined, wenn alter nicht existiert. Prüfe die Schreibweise der Eigenschaft vor weiteren Berechnungen. Du kannst `person.alter = 30` ergänzen und danach erneut lesen.","code":"const person = { name: 'Amina', ort: 'Bonn' }; console.log(person.name);","erklaerung":"`person.alter` liefert undefined, wenn alter nicht existiert. Prüfe die Schreibweise der Eigenschaft vor weiteren Berechnungen.","tiefer":["Eine fehlende Eigenschaft liefert `undefined`. Problematisch wird es eine Ebene tiefer: `person.adresse.ort` erzeugt einen TypeError, wenn `adresse` fehlt. Der Operator `?.` (optionale Verkettung) verhindert das: `person.adresse?.ort` ergibt dann einfach `undefined`.","Mit `??` gibst du einen Ersatzwert an: `person.ort ?? 'unbekannt'`. Anders als `||` greift `??` nur bei `null` und `undefined`, nicht bei `0` oder einem leeren Text. Ob eine Eigenschaft existiert, prüfst du sauber mit `'ort' in person` oder `Object.hasOwn(person, 'ort')`."]}],"beispiel":{"html":"<h1>Objekte</h1><p id='ausgabe'></p>","css":"","js":""},"aufgabe":{"text":"Setze das Beispiel im Editor um und kontrolliere die Vorschau oder Konsole.","tipp":"Vergleiche die Schreibweise mit dem Codebeispiel.","pruefungen":[{"beschreibung":"Passende HTML-Struktur vorhanden.","test":"p3-5-html"},{"beschreibung":"JavaScript enthält die geübte Technik.","test":"p3-5-js"}],"loesung":{"html":"<h1>Objekte</h1><p id='ausgabe'></p>","css":"","js":"const person = { name: 'Amina', ort: 'Bonn' }; console.log(person.name);"}},"fehler":[{"titel":"Eigenschaftsname falsch geschrieben","text":"Falsch: `console.log(person.Name);` liefert `undefined`, obwohl `name` gespeichert ist. Eigenschaftsnamen unterscheiden Groß- und Kleinschreibung. Richtig: `console.log(person.name);` zeigt `Amina`."},{"titel":"const-Objekt neu zugewiesen","text":"Falsch: `const person = { name: 'Amina' }; person = { name: 'Mina' };` erzeugt `TypeError: Assignment to constant variable.`. Du darfst die const-Bindung nicht ersetzen. Richtig: `person.name = 'Mina';` ändert die Eigenschaft."}],"quiz":[{"frage":"Was liefert person.name?","antworten":["Ort","Name","Objektlänge"],"richtig":1,"erklaerung":"Hier passt „Name“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Was bedeutet undefined?","antworten":["Wert fehlt möglicherweise","Alles ist gelöscht","Wert ist null"],"richtig":0,"erklaerung":"Hier passt „Wert fehlt möglicherweise“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Was darfst du ändern?","antworten":["const person neu setzen","const entfernen","person.ort"],"richtig":2,"erklaerung":"Hier passt „person.ort“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion."]}],"merke":["Bei Objekte ist die genaue JavaScript-Schreibweise wichtig.","Nutze die Lösung `const person = { name: 'Amina', ort: 'Bonn' }; console.log(person.name);` als Vergleich für deine eigene Übung."]},{"id":"p3-6","title":"DOM","minutes":25,"ziel":"HTML-Elemente finden und sicher verändern","schritte":[{"titel":"DOM als Dokumentstruktur","text":"Der Browser stellt HTML als Dokumentstruktur bereit. Diese Struktur heißt DOM. JavaScript kann darin gezielt Elemente suchen. Ein Stadtplan zeigt Straßen und Häuser; das DOM bildet die Struktur einer Webseite ab. `document.querySelector('#ausgabe')` sucht die passende ID. Das Zeichen # bedeutet, dass du ein bestimmtes Element meinst. Lege ein `<p id='ausgabe'>` an, damit die Suche erfolgreich ist.","code":"const ausgabe = document.querySelector('#ausgabe'); if (ausgabe) ausgabe.textContent = 'Willkommen';","erklaerung":"`document.querySelector('#ausgabe')` sucht die passende ID. Das Zeichen # bedeutet, dass du ein bestimmtes Element meinst.","tiefer":["DOM heißt Document Object Model. Der Browser übersetzt den HTML-Text in einen Baum aus Objekten: Das Dokument ist die Wurzel, darunter liegen `html`, `head` und `body`, und darunter die einzelnen Elemente. Text zwischen den Tags bildet eigene Textknoten.","Ändert JavaScript den DOM-Baum, aktualisiert der Browser die Anzeige automatisch. Der ursprüngliche HTML-Quelltext bleibt dabei unverändert – in den Entwicklerwerkzeugen siehst du unter „Elements“ den aktuellen DOM, unter „Seitenquelltext anzeigen“ das ursprüngliche HTML."]},{"titel":"Element per ID auswählen","text":"querySelector findet ein Element anhand eines CSS-Selektors. Das Zeichen # steht für eine ID. Stimmen die Namen nicht überein, kommt null zurück. Eine Hausnummer muss genau stimmen, sonst findest du das Gebäude nicht. `const ausgabe = document.querySelector('#ausgabe');` speichert das gefundene Element. Ist die ID anders geschrieben, steht in ausgabe der Wert null. Prüfe den Namen im HTML und im JavaScript Zeichen für Zeichen.","code":"const ausgabe = document.querySelector('#ausgabe'); if (ausgabe) ausgabe.textContent = 'Willkommen';","erklaerung":"`const ausgabe = document.querySelector('#ausgabe');` speichert das gefundene Element. Ist die ID anders geschrieben, steht in ausgabe der Wert null.","tiefer":["`querySelector` liefert das erste passende Element, `querySelectorAll` alle als Liste, die du mit `for...of` durchlaufen kannst. Du kannst jeden CSS-Selektor verwenden: `'.hinweis'`, `'nav a'` oder `'[type=email]'`. Daneben gibt es das ältere, schnelle `document.getElementById('ausgabe')`.","Eine Suche im DOM kostet etwas Zeit. Speichere ein Element deshalb in einer Variable, wenn du es mehrmals brauchst, statt es jedes Mal neu zu suchen. In großen Anwendungen bündelt man solche Verweise oft am Anfang eines Skripts."]},{"titel":"textContent einsetzen","text":"textContent ersetzt den sichtbaren Text. Anders als innerHTML behandelt es Nutzereingaben nicht als HTML-Markup. Das hilft gegen unerwünschte Codeausführung. Ein Hinweisschild kann einen neuen Text bekommen, ohne dass du das ganze Schild austauschst. `ausgabe.textContent = 'Willkommen';` ersetzt den sichtbaren Inhalt. Auch Zeichen wie `<` werden dabei als Text behandelt. Das ist wichtig, wenn später fremde Eingaben angezeigt werden.","code":"const ausgabe = document.querySelector('#ausgabe'); if (ausgabe) ausgabe.textContent = 'Willkommen';","erklaerung":"`ausgabe.textContent = 'Willkommen';` ersetzt den sichtbaren Inhalt. Auch Zeichen wie `<` werden dabei als Text behandelt.","tiefer":["`innerHTML` wertet den zugewiesenen Text als HTML aus. Stammt der Text von Nutzern, könnte jemand darin ein Skript einschleusen, das im Browser anderer Besucher ausgeführt wird. Diese Angriffsart heißt Cross-Site-Scripting (XSS) und gehört zu den häufigsten Sicherheitslücken im Web.","`textContent` zeigt alles als reinen Text, auch spitze Klammern. Für neue Elemente nutzt du `document.createElement` und setzt Inhalte mit `textContent`. Klassen änderst du mit `element.classList.add('aktiv')` und `remove`, statt Stile direkt im Skript festzulegen."]},{"titel":"Auf Existenz prüfen","text":"Prüfe das Element vor dem Zugriff. Eine einfache if-Abfrage verhindert Fehler bei null. Platziere das Skript so, dass das HTML bereits geladen wurde. Ein Briefkasten muss montiert sein, bevor du einen Brief einwerfen kannst. `if (ausgabe)` prüft, ob das Element gefunden wurde. Erst im erfolgreichen Zweig änderst du textContent.","code":"const ausgabe = document.querySelector('#ausgabe'); if (ausgabe) ausgabe.textContent = 'Willkommen';","erklaerung":"`if (ausgabe)` prüft, ob das Element gefunden wurde. Erst im erfolgreichen Zweig änderst du textContent.","tiefer":["Ein `script` im `head` läuft, bevor der Browser den `body` gelesen hat – `querySelector` findet dann noch nichts und liefert `null`. Abhilfe: das Skript am Ende des `body` einbinden oder im `head` mit dem Attribut `defer` laden. Mit `defer` wartet der Browser, bis das HTML vollständig gelesen ist.","Eine Prüfung wie `if (ausgabe)` macht Code robust, wenn ein Element auf manchen Seiten fehlt. Die Kurzform `ausgabe?.append(...)` erledigt Prüfung und Aufruf auf einmal. In der Konsole zeigt ein Fehler wie „Cannot set properties of null“ genau dieses Problem an."]}],"beispiel":{"html":"<h1>DOM</h1><p id='ausgabe'>Vorher</p>","css":"","js":""},"aufgabe":{"text":"Setze das Beispiel im Editor um und kontrolliere die Vorschau oder Konsole.","tipp":"Vergleiche die Schreibweise mit dem Codebeispiel.","pruefungen":[{"beschreibung":"Passende HTML-Struktur vorhanden.","test":"p3-6-html"},{"beschreibung":"JavaScript enthält die geübte Technik.","test":"p3-6-js"}],"loesung":{"html":"<h1>DOM</h1><p id='ausgabe'>Vorher</p>","css":"","js":"const ausgabe = document.querySelector('#ausgabe'); if (ausgabe) ausgabe.textContent = 'Willkommen';"}},"fehler":[{"titel":"ID im HTML stimmt nicht","text":"Falsch: `document.querySelector('#anzeige').textContent = 'Hallo';` kann `TypeError: Cannot set properties of null` auslösen, wenn das HTML nur `id='ausgabe'` enthält. Richtig: `document.querySelector('#ausgabe').textContent = 'Hallo';` trifft das vorhandene Element."},{"titel":"innerHTML für fremde Texte benutzt","text":"Falsch: `ausgabe.innerHTML = eingabe;` kann eingegebenes HTML als echte Elemente darstellen, statt es als Text zu zeigen. Richtig: `ausgabe.textContent = eingabe;` zeigt auch `<b>Hallo</b>` wörtlich an."}],"quiz":[{"frage":"Was findet #ausgabe?","antworten":["Alle Links","Element mit passender ID","Ein Stylesheet"],"richtig":1,"erklaerung":"Hier passt „Element mit passender ID“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Was setzt sicheren Text?","antworten":["textContent","innerHTML","eval"],"richtig":0,"erklaerung":"Hier passt „textContent“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Was bedeutet null?","antworten":["Leerer Text","Keine CSS-Regel","Kein Element gefunden"],"richtig":2,"erklaerung":"Hier passt „Kein Element gefunden“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion."]}],"merke":["Bei DOM ist die genaue JavaScript-Schreibweise wichtig.","Nutze die Lösung `const ausgabe = document.querySelector('#ausgabe'); if (ausgabe) ausgabe.textContent = 'Willkommen';` als Vergleich für deine eigene Übung."]},{"id":"p3-7","title":"Events","minutes":25,"ziel":"Klicks mit addEventListener verarbeiten","schritte":[{"titel":"Klick als Ereignis","text":"Ein Event ist ein Ereignis wie ein Klick. JavaScript kann darauf warten. So wird eine Seite interaktiv. Eine Türklingel löst erst beim Drücken ein Signal aus; ein Klick ist ähnlich. `addEventListener('click', ...)` wartet auf das Ereignis. Die Funktion wird nicht bereits beim Laden der Seite ausgeführt. So bleibt der Knopf für weitere Klicks bereit.","code":"const knopf = document.querySelector('#knopf'); const ausgabe = document.querySelector('#ausgabe'); if (knopf && ausgabe) knopf.addEventListener('click', () => { ausgabe.textContent = 'Gespeichert'; });","erklaerung":"`addEventListener('click', ...)` wartet auf das Ereignis. Die Funktion wird nicht bereits beim Laden der Seite ausgeführt.","tiefer":["Der Browser erzeugt laufend Ereignisse: Klicks, Tastendrücke, Eingaben in Felder (`input`), Absenden von Formularen (`submit`), Scrollen und das Laden der Seite. JavaScript im Browser ist ereignisgesteuert: Code läuft meist als Reaktion auf so ein Ereignis.","Ereignisse steigen im DOM-Baum nach oben (Bubbling): Ein Klick auf einen Link löst das Ereignis auch an der umgebenden Liste und am Dokument aus. Deshalb kann ein einziger Listener an einer Liste alle Klicks auf ihre Einträge abfangen. Dieses Muster heißt Event-Delegation."]},{"titel":"Listener registrieren","text":"addEventListener verbindet ein Element mit einer Funktion. Die Funktion wird erst beim Ereignis ausgeführt. Achte auf die Schreibweise click. Ein Empfangsdienst erhält eine Telefonnummer, nicht einen schon beendeten Anruf. `knopf.addEventListener('click', melden)` übergibt die Funktion selbst. Mit `melden()` würdest du sie bereits beim Registrieren aufrufen. Achte deshalb darauf, ob hinter dem Funktionsnamen Klammern stehen.","code":"const knopf = document.querySelector('#knopf'); const ausgabe = document.querySelector('#ausgabe'); if (knopf && ausgabe) knopf.addEventListener('click', () => { ausgabe.textContent = 'Gespeichert'; });","erklaerung":"`knopf.addEventListener('click', melden)` übergibt die Funktion selbst. Mit `melden()` würdest du sie bereits beim Registrieren aufrufen.","tiefer":["Die Listener-Funktion bekommt automatisch ein Ereignisobjekt als Parameter, meist `event` oder `e` genannt. `event.target` ist das Element, auf das geklickt wurde, `event.key` die gedrückte Taste. Mit `event.preventDefault()` verhinderst du das Standardverhalten, etwa das Neuladen beim Absenden eines Formulars.","Ein Element kann mehrere Listener für dasselbe Ereignis haben. Mit `removeEventListener` entfernst du einen wieder – dafür brauchst du dieselbe Funktion, also eine benannte, keine anonyme. Mit der Option `{ once: true }` läuft ein Listener nur ein einziges Mal."]},{"titel":"Rückmeldung zeigen","text":"Im Listener kannst du Text ändern. Eine Meldung wie Gespeichert bestätigt die Aktion. Das ist für Nutzerinnen und Nutzer eine wichtige Rückmeldung. Eine Quittung bestätigt eine Zahlung; ein Statussatz bestätigt einen Klick. `ausgabe.textContent = 'Gespeichert';` aktualisiert die Meldung. Die Änderung erfolgt innerhalb der Klick-Funktion. Klicke zweimal und kontrolliere, dass die Meldung verständlich bleibt.","code":"const knopf = document.querySelector('#knopf'); const ausgabe = document.querySelector('#ausgabe'); if (knopf && ausgabe) knopf.addEventListener('click', () => { ausgabe.textContent = 'Gespeichert'; });","erklaerung":"`ausgabe.textContent = 'Gespeichert';` aktualisiert die Meldung. Die Änderung erfolgt innerhalb der Klick-Funktion.","tiefer":["Gute Rückmeldung folgt sofort und sagt klar, was passiert ist. Bei längeren Vorgängen zeigt man zuerst einen Zwischenstand wie „Wird gespeichert …“ und deaktiviert den Knopf, damit niemand doppelt klickt. Fehler werden mit einer verständlichen Erklärung gemeldet.","Für Vorleseprogramme gibt es Live-Bereiche: Ein Element mit `aria-live=\"polite\"` wird vorgelesen, sobald sich sein Text ändert. So erfahren auch blinde Menschen, dass ihre Aktion geklappt hat. Wichtig ist, dass die Meldung als Text erscheint und nicht nur als Farbwechsel."]},{"titel":"Tastatur prüfen","text":"Ein echtes button-Element funktioniert auch mit der Tastatur. Teste Tab und Enter. Ein klickbarer Absatz ist dafür keine gleichwertige Lösung. Eine barrierefreie Tür lässt sich auf mehreren Wegen öffnen. Ein HTML-button reagiert neben der Maus auch auf Tastatureingaben. Erreiche den Knopf mit Tab und aktiviere ihn mit Enter.","code":"const knopf = document.querySelector('#knopf'); const ausgabe = document.querySelector('#ausgabe'); if (knopf && ausgabe) knopf.addEventListener('click', () => { ausgabe.textContent = 'Gespeichert'; });","erklaerung":"Ein HTML-button reagiert neben der Maus auch auf Tastatureingaben. Erreiche den Knopf mit Tab und aktiviere ihn mit Enter.","tiefer":["Ein `button` löst das `click`-Ereignis auch bei Enter und Leertaste aus. Hängst du dagegen einen Klick-Listener an ein `div`, erreichen Tastaturnutzer es nicht einmal mit Tab. Man müsste `tabindex`, eine Rolle und eigene Tastenbehandlung ergänzen – fehleranfällig und unnötig.","Teste jede interaktive Seite ohne Maus: Mit Tab vorwärts, mit Umschalt+Tab zurück, mit Enter oder Leertaste auslösen. Ein sichtbarer Fokusrahmen muss dabei immer zeigen, wo man gerade ist. Entferne ihn nie ersatzlos mit `outline: none`."]}],"beispiel":{"html":"<h1>Events</h1><button id='knopf' type='button'>Speichern</button><p id='ausgabe'></p>","css":"","js":""},"aufgabe":{"text":"Setze das Beispiel im Editor um und kontrolliere die Vorschau oder Konsole.","tipp":"Vergleiche die Schreibweise mit dem Codebeispiel.","pruefungen":[{"beschreibung":"Passende HTML-Struktur vorhanden.","test":"p3-7-html"},{"beschreibung":"JavaScript enthält die geübte Technik.","test":"p3-7-js"}],"loesung":{"html":"<h1>Events</h1><button id='knopf' type='button'>Speichern</button><p id='ausgabe'></p>","css":"","js":"const knopf = document.querySelector('#knopf'); const ausgabe = document.querySelector('#ausgabe'); if (knopf && ausgabe) knopf.addEventListener('click', () => { ausgabe.textContent = 'Gespeichert'; });"}},"fehler":[{"titel":"Funktion sofort statt beim Klick ausgeführt","text":"Falsch: `knopf.addEventListener('click', melden());` ruft melden sofort auf; beim Klick passiert danach nichts oder ein TypeError entsteht. Richtig: `knopf.addEventListener('click', melden);` übergibt die Funktion ohne Klammern."},{"titel":"Listener an null registriert","text":"Falsch: `document.querySelector('#knop').addEventListener('click', melden);` löst `TypeError: Cannot read properties of null` aus, wenn der Knopf `id='knopf'` heißt. Richtig: `document.querySelector('#knopf').addEventListener('click', melden);`."}],"quiz":[{"frage":"Wie heißt das Klick-Ereignis?","antworten":["submit","click","change"],"richtig":1,"erklaerung":"Hier passt „click“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Was registriert einen Listener?","antworten":["addEventListener","querySelectorAll","textContent"],"richtig":0,"erklaerung":"Hier passt „addEventListener“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Warum button verwenden?","antworten":["Es lädt schneller","Es braucht kein CSS","Es ist per Tastatur bedienbar"],"richtig":2,"erklaerung":"Hier passt „Es ist per Tastatur bedienbar“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion."]}],"merke":["Bei Events ist die genaue JavaScript-Schreibweise wichtig.","Nutze die Lösung `const knopf = document.querySelector('#knopf'); const ausgabe = document.querySelector('#ausgabe'); if (knopf && ausgabe) knopf.addEventListener('click', () => { ausgabe.textContent = 'Gespeichert'; });` als Vergleich für deine eigene Übung."]},{"id":"p3-8","title":"Konsole","minutes":25,"ziel":"JavaScript-Fehler systematisch untersuchen","schritte":[{"titel":"Werte protokollieren","text":"console.log zeigt Werte in der Entwicklerkonsole. Damit erkennst du Zwischenergebnisse. Beschrifte deine Ausgaben verständlich. Ein Techniker liest die Anzeige eines Geräts, bevor er etwas austauscht. `console.log('Gefunden:', Boolean(element));` zeigt einen beschrifteten Wert. Boolean wandelt die Existenz des Elements in true oder false um. So erkennst du, ob die Suche überhaupt erfolgreich war.","code":"const element = document.querySelector('#ausgabe'); console.log('Gefunden:', Boolean(element));","erklaerung":"`console.log('Gefunden:', Boolean(element));` zeigt einen beschrifteten Wert. Boolean wandelt die Existenz des Elements in true oder false um.","tiefer":["Neben `console.log` gibt es `console.warn` und `console.error`, die farblich hervorgehoben werden, sowie `console.table` für Arrays und Objekte als übersichtliche Tabelle. Mit Filtern in der Konsole kannst du gezielt nur Fehler oder nur bestimmte Texte anzeigen.","Gibst du ein Objekt mit `console.log` aus, zeigt manche Konsole beim Aufklappen den aktuellen Zustand, nicht den Zustand zum Zeitpunkt der Ausgabe. Willst du einen Zwischenstand festhalten, gib eine Kopie aus, etwa `console.log(JSON.stringify(daten))`."]},{"titel":"SyntaxError erkennen","text":"Ein SyntaxError weist auf ungültige Schreibweise hin. Prüfe Klammern und Anführungszeichen. Die Zeilennummer hilft beim Suchen. Ein falsch geschriebenes Wort auf einem Formular verhindert das Verständnis. `console.log('Hallo'` fehlt die schließende runde Klammer. Der Browser meldet einen SyntaxError und führt den Code nicht aus. Ergänze `);` und starte die Prüfung erneut.","code":"const element = document.querySelector('#ausgabe'); console.log('Gefunden:', Boolean(element));","erklaerung":"`console.log('Hallo'` fehlt die schließende runde Klammer. Der Browser meldet einen SyntaxError und führt den Code nicht aus.","tiefer":["Ein SyntaxError entsteht schon beim Einlesen des Skripts. Deshalb läuft dann das ganze Skript nicht, nicht nur die fehlerhafte Zeile. Die Konsole nennt Datei und Zeilennummer; ein Klick darauf öffnet die Stelle im Quelltext.","Typische Ursachen sind vergessene Klammern, fehlende Anführungszeichen und Tippfehler in Schlüsselwörtern. Editoren mit Syntaxhervorhebung zeigen solche Fehler oft schon beim Schreiben durch Farben oder Wellenlinien. Ein Formatierer wie Prettier macht falsch geschlossene Klammern zusätzlich sichtbar."]},{"titel":"TypeError verstehen","text":"Ein TypeError kann bei einem Zugriff auf null entstehen. Kontrolliere das Ergebnis von querySelector. Eine if-Abfrage schützt vor dem Zugriff. Eine Lieferung an eine unbekannte Adresse kann nicht ankommen. `document.querySelector('#fehlt')` liefert null, wenn es kein Ziel gibt. Ein direkter Zugriff auf `.textContent` erzeugt dann einen TypeError. Mit `if (element)` vermeidest du diesen Zugriff.","code":"const element = document.querySelector('#ausgabe'); console.log('Gefunden:', Boolean(element));","erklaerung":"`document.querySelector('#fehlt')` liefert null, wenn es kein Ziel gibt. Ein direkter Zugriff auf `.textContent` erzeugt dann einen TypeError.","tiefer":["Ein TypeError tritt erst zur Laufzeit auf, wenn ein Wert nicht den erwarteten Typ hat, etwa wenn du auf eine Eigenschaft von `null` zugreifst oder etwas aufrufst, das keine Funktion ist. Die Meldung „Cannot read properties of null (reading 'textContent')“ sagt genau, welcher Zugriff scheiterte.","Ein ReferenceError bedeutet dagegen, dass ein Name gar nicht existiert, meist wegen eines Tippfehlers. Lies die Meldung vollständig: Sie enthält Fehlertyp, Beschreibung und einen Stack-Trace mit der Kette der Funktionsaufrufe bis zur Fehlerstelle."]},{"titel":"Gezielt erneut testen","text":"Ändere jeweils nur eine Stelle. Starte danach den Test erneut. Entferne überflüssige Debug-Ausgaben vor der Veröffentlichung. Beim Reparieren eines Fahrrads prüfst du nach jeder Änderung nur das betroffene Teil. Setze eine beschriftete console.log-Ausgabe vor den verdächtigen Abschnitt. Beobachte den Wert und ändere danach genau eine Anweisung. Wiederhole den Test, bis die Fehlermeldung verschwindet.","code":"const element = document.querySelector('#ausgabe'); console.log('Gefunden:', Boolean(element));","erklaerung":"Setze eine beschriftete console.log-Ausgabe vor den verdächtigen Abschnitt. Beobachte den Wert und ändere danach genau eine Anweisung.","tiefer":["Die Entwicklerwerkzeuge enthalten einen Debugger: Mit einem Haltepunkt (Breakpoint) – ein Klick auf die Zeilennummer im Tab „Sources“ – hält das Skript an dieser Stelle an. Dann kannst du alle Variablen ansehen und Zeile für Zeile weitergehen. Im Code bewirkt die Anweisung `debugger;` dasselbe.","Eine bewährte Methode ist das Gummienten-Debugging: Erkläre jemandem – oder einer Gummiente – Zeile für Zeile, was dein Code tun soll. Beim lauten Erklären fällt der Fehler oft selbst auf. Dahinter steckt dasselbe Prinzip wie beim schrittweisen Testen: Annahmen gezielt überprüfen."]}],"beispiel":{"html":"<h1>Konsole</h1><p id='ausgabe'>Prüfen</p>","css":"","js":""},"aufgabe":{"text":"Setze das Beispiel im Editor um und kontrolliere die Vorschau oder Konsole.","tipp":"Vergleiche die Schreibweise mit dem Codebeispiel.","pruefungen":[{"beschreibung":"Passende HTML-Struktur vorhanden.","test":"p3-8-html"},{"beschreibung":"JavaScript enthält die geübte Technik.","test":"p3-8-js"}],"loesung":{"html":"<h1>Konsole</h1><p id='ausgabe'>Prüfen</p>","css":"","js":"const element = document.querySelector('#ausgabe'); console.log('Gefunden:', Boolean(element));"}},"fehler":[{"titel":"Syntaxfehler überlesen","text":"Falsch: `console.log('Hallo'` erzeugt `SyntaxError: missing ) after argument list` oder eine entsprechende Syntaxmeldung. Die schließende Klammer fehlt. Richtig: `console.log('Hallo');` lässt sich ausführen."},{"titel":"Auf null ohne Prüfung zugegriffen","text":"Falsch: `document.querySelector('#fehlt').textContent = 'OK';` löst `TypeError: Cannot set properties of null` aus, wenn es das Element nicht gibt. Richtig: `const el = document.querySelector('#fehlt'); if (el) el.textContent = 'OK';`."}],"quiz":[{"frage":"Was zeigt console.log?","antworten":["Nur Bilder","Werte in der Konsole","Nur HTML"],"richtig":1,"erklaerung":"Hier passt „Werte in der Konsole“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Was ist SyntaxError?","antworten":["Ungültige Schreibweise","Fehlendes Internet","Falsche Farbe"],"richtig":0,"erklaerung":"Hier passt „Ungültige Schreibweise“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Was vor textContent prüfen?","antworten":["Schriftgröße","Fensterhöhe","Element ist nicht null"],"richtig":2,"erklaerung":"Hier passt „Element ist nicht null“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion."]}],"merke":["Bei Konsole ist die genaue JavaScript-Schreibweise wichtig.","Nutze die Lösung `const element = document.querySelector('#ausgabe'); console.log('Gefunden:', Boolean(element));` als Vergleich für deine eigene Übung."]},{"id":"p3-9","title":"Projekt: To-do-Liste","minutes":25,"ziel":"Eine kleine Aufgabenliste mit Eingabe und Knopf bauen","schritte":[{"titel":"Eingabe beschriften","text":"Eine Aufgabenliste braucht ein Eingabefeld. Verbinde label und input über for und id. Der Knopf startet das Hinzufügen. Ein Notizblock braucht eine Zeile für jede neue Aufgabe. `<label for='aufgabe'>` beschreibt das Eingabefeld. Das zugehörige input hat die ID aufgabe.","code":"const feld = document.querySelector('#aufgabe'); const liste = document.querySelector('#liste'); document.querySelector('#hinzufuegen').addEventListener('click', () => { const text = feld.value.trim(); if (!text) return; const li = document.createElement('li'); li.textContent = text; liste.appendChild(li); feld.value = ''; });","erklaerung":"`<label for='aufgabe'>` beschreibt das Eingabefeld. Das zugehörige input hat die ID aufgabe.","tiefer":["Pack Feld und Knopf in ein `form`-Element und reagiere auf das Ereignis `submit`. Dann funktioniert das Hinzufügen per Klick und per Enter-Taste gleichermaßen. Vergiss im Listener `event.preventDefault()`, sonst lädt der Browser die Seite neu und die Liste ist leer.","Die Aufgabenliste selbst ist am besten ein `ul`-Element. Vorleseprogramme sagen dann an, wie viele Einträge die Liste hat. Ein Attribut wie `maxlength` begrenzt die Länge der Eingabe und schützt so das Layout vor extrem langen Texten."]},{"titel":"Leere Aufgaben vermeiden","text":"Mit value liest du die Eingabe. trim entfernt Leerzeichen am Anfang und Ende. Eine leere Eingabe darf keinen Eintrag erzeugen. Auf einem Einkaufszettel hilft eine leere Zeile niemandem. `feld.value.trim()` entfernt Leerzeichen am Rand. `if (!text) return;` beendet den Klickablauf bei leerem Text. Teste Eingaben mit nur drei Leerzeichen und mit einem echten Wort.","code":"const feld = document.querySelector('#aufgabe'); const liste = document.querySelector('#liste'); document.querySelector('#hinzufuegen').addEventListener('click', () => { const text = feld.value.trim(); if (!text) return; const li = document.createElement('li'); li.textContent = text; liste.appendChild(li); feld.value = ''; });","erklaerung":"`feld.value.trim()` entfernt Leerzeichen am Rand. `if (!text) return;` beendet den Klickablauf bei leerem Text.","tiefer":["`value` liefert immer einen String, auch bei Zahlenfeldern. `trim()` entfernt Leerzeichen, Tabs und Zeilenumbrüche an beiden Enden, nicht in der Mitte. Ein leerer String ist „falsy“, deshalb reicht die Prüfung `if (!text) return;`.","Gib eine kurze Rückmeldung, wenn eine leere Eingabe abgelehnt wird, und setze den Fokus mit `feld.focus()` zurück ins Feld. So weiß die Person sofort, was zu tun ist. Prüfe auch auf doppelte Einträge, falls das für deine Liste sinnvoll ist."]},{"titel":"Listeneinträge erzeugen","text":"createElement erzeugt ein neues li-Element. Mit textContent setzt du den Aufgabentext sicher. appendChild fügt den Eintrag in die Liste ein. Eine neue Karteikarte wird erst erstellt und danach beschriftet. `document.createElement('li')` erzeugt einen Listeneintrag. `li.textContent = text` schreibt die Aufgabe sicher hinein. `liste.appendChild(li)` hängt den Eintrag an die sichtbare Liste.","code":"const feld = document.querySelector('#aufgabe'); const liste = document.querySelector('#liste'); document.querySelector('#hinzufuegen').addEventListener('click', () => { const text = feld.value.trim(); if (!text) return; const li = document.createElement('li'); li.textContent = text; liste.appendChild(li); feld.value = ''; });","erklaerung":"`document.createElement('li')` erzeugt einen Listeneintrag. `li.textContent = text` schreibt die Aufgabe sicher hinein.","tiefer":["Neue Elemente zuerst vollständig vorzubereiten und dann einzufügen ist effizient, weil der Browser die Anzeige nur einmal neu berechnen muss. Statt `appendChild` kannst du auch das modernere `append` verwenden, das mehrere Elemente und sogar Texte auf einmal annimmt.","Um Aufgaben abhaken oder löschen zu können, bekommt jeder Eintrag einen eigenen Knopf. Mit Event-Delegation reicht ein einziger Listener an der Liste, der über `event.target` erkennt, welcher Knopf gedrückt wurde. So funktionieren auch Einträge, die erst später hinzukommen."]},{"titel":"Aufgaben nach Klick anzeigen","text":"Leere das Feld nach dem Hinzufügen. Probiere mehrere Aufgaben nacheinander. Kontrolliere die Bedienung auch auf einem kleinen Handy. Nach dem Eintragen einer Aufgabe ist der Stift wieder frei für die nächste. `feld.value = ''` leert das Eingabefeld nach dem Hinzufügen. Ein erneuter Klick mit leerem Feld darf keinen Eintrag erzeugen. Teste zwei unterschiedliche Aufgaben nacheinander.","code":"const feld = document.querySelector('#aufgabe'); const liste = document.querySelector('#liste'); document.querySelector('#hinzufuegen').addEventListener('click', () => { const text = feld.value.trim(); if (!text) return; const li = document.createElement('li'); li.textContent = text; liste.appendChild(li); feld.value = ''; });","erklaerung":"`feld.value = ''` leert das Eingabefeld nach dem Hinzufügen. Ein erneuter Klick mit leerem Feld darf keinen Eintrag erzeugen.","tiefer":["Damit die Liste ein Neuladen übersteht, speicherst du sie mit `localStorage.setItem('aufgaben', JSON.stringify(liste))` und liest sie beim Start mit `JSON.parse` wieder ein. Die Daten bleiben dann nur in diesem Browser auf diesem Gerät gespeichert und werden nicht übertragen.","Eine saubere Struktur trennt Daten und Anzeige: Ein Array hält die Aufgaben, und eine Funktion `zeichnen()` baut die Liste aus diesem Array neu auf. Jede Änderung verändert zuerst das Array und ruft dann `zeichnen()` auf. Dieses Prinzip ist die Grundidee moderner Frameworks wie React und Vue."]}],"beispiel":{"html":"<h1>Aufgabenliste</h1><label for='aufgabe'>Neue Aufgabe</label><input id='aufgabe'><button id='hinzufuegen' type='button'>Hinzufügen</button><ul id='liste'></ul>","css":"","js":""},"aufgabe":{"text":"Setze das Beispiel im Editor um und kontrolliere die Vorschau oder Konsole.","tipp":"Vergleiche die Schreibweise mit dem Codebeispiel.","pruefungen":[{"beschreibung":"Passende HTML-Struktur vorhanden.","test":"p3-9-html"},{"beschreibung":"JavaScript enthält die geübte Technik.","test":"p3-9-js"}],"loesung":{"html":"<h1>Aufgabenliste</h1><label for='aufgabe'>Neue Aufgabe</label><input id='aufgabe'><button id='hinzufuegen' type='button'>Hinzufügen</button><ul id='liste'></ul>","css":"","js":"const feld = document.querySelector('#aufgabe'); const liste = document.querySelector('#liste'); document.querySelector('#hinzufuegen').addEventListener('click', () => { const text = feld.value.trim(); if (!text) return; const li = document.createElement('li'); li.textContent = text; liste.appendChild(li); feld.value = ''; });"}},"fehler":[{"titel":"Leere Aufgaben gespeichert","text":"Falsch: `aufgaben.push(feld.value);` übernimmt auch `   ` als Aufgabe; in der Vorschau erscheint ein leerer Listeneintrag. Richtig: `const text = feld.value.trim(); if (!text) return; aufgaben.push(text);`."},{"titel":"Eingabetext mit innerHTML eingesetzt","text":"Falsch: `liste.innerHTML += '<li>' + feld.value + '</li>';` interpretiert eingegebenes HTML und kann unerwünschte Elemente erzeugen. Richtig: `const li = document.createElement('li'); li.textContent = feld.value; liste.appendChild(li);`."}],"quiz":[{"frage":"Was entfernt trim?","antworten":["Rand-Leerzeichen","Alle Zahlen","Alle Einträge"],"richtig":0,"erklaerung":"Hier passt „Rand-Leerzeichen“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Wie erzeugst du li?","antworten":["querySelector","createElement","addEventListener"],"richtig":1,"erklaerung":"Hier passt „createElement“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Wie zeigst du Text sicher?","antworten":["eval","innerHTML","textContent"],"richtig":2,"erklaerung":"Hier passt „textContent“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion."]}],"merke":["Bei Projekt: To-do-Liste ist die genaue JavaScript-Schreibweise wichtig.","Nutze die Lösung `const feld = document.querySelector('#aufgabe'); const liste = document.querySelector('#liste'); document.querySelector('#hinzufuegen').addEventListener('click', () => { const text = feld.value.trim(); if (!text) return; const li = document.createElement('li'); li.textContent = text; liste.appendChild(li); feld.value = ''; });` als Vergleich für deine eigene Übung."]}];if(typeof module!=="undefined"&&module.exports)module.exports=root.SDAkademieKurse["javascript"];})(typeof window!=="undefined"?window:globalThis);
